import React, { PropsWithChildren } from 'react';

import { SparklineRenderer } from './components/SparklineRenderer.js';
import { iterateSlots } from './functions/iterate-slots.js';
import { Threshold } from './slots/Threshold.js';
import { YAxis } from './slots/YAxis.js';
import { SparklineVariant } from './types/sparkline.js';
import { EmptyStateSlot } from '../core/slots/chart-states/EmptyStateSlot.js';
import { ErrorStateSlot } from '../core/slots/chart-states/ErrorStateSlot.js';
import { SeriesCurve, Timeseries } from '../core/types/timeseries.js';

/** Sparkline props*/
export interface SparklineProps {
  /** Data to show */
  data: Timeseries | Timeseries[];
  /** Sparkline color */
  color?: string;
  /** Sparkline variant (line, area) */
  variant?: SparklineVariant;
  /** Whether Sparkline shows X Axis ticks or not */
  showTicks?: boolean;
  /** When true: Sets an overlay with default loader. */
  loading?: boolean;
  /** Gap policy */
  gapPolicy?: 'connect' | 'gap';
  /**
   * Curve shape of the series
   * @defaultValue 'linear'
   */
  curve?: SeriesCurve;
}

export const _Sparkline = ({
  children,
  ...props
}: PropsWithChildren<SparklineProps>) => {
  const slots = iterateSlots(children);

  return (
    <SparklineRenderer
      {...props}
      thresholds={slots.thresholds}
      yAxis={slots.yAxis}
    >
      {children}
    </SparklineRenderer>
  );
};

_Sparkline['displayName'] = 'Sparkline';

/**
 * The `Sparkline` is a compact and simple data visualization that displays
 * a trend or pattern of data in a small, condensed format. It typically consists
 * of a single line or area graph, without axes or labels, that represents the
 * variation of data points over time.
 */
export const Sparkline = Object.assign(_Sparkline, {
  Threshold,
  EmptyState: EmptyStateSlot,
  ErrorState: ErrorStateSlot,
  YAxis,
});
